// HasReadings applies the HasEdge predicate on the "readings" edge.
func HasReadings() predicate.Meter {
	return predicate.Meter(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, ReadingsTable, ReadingsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasReadingsWith applies the HasEdge predicate on the "readings" edge with a given conditions (other predicates).
func HasReadingsWith(preds ...predicate.MeterReading) predicate.Meter {
	return predicate.Meter(func(s *sql.Selector) {
		step := newReadingsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Meter) predicate.Meter {
	return predicate.Meter(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Meter) predicate.Meter {
	return predicate.Meter(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Meter) predicate.Meter {
	return predicate.Meter(sql.NotPredicates(p))
}
